<?php
require_once __DIR__.'/common.php';
[$period,$start,$end,$message]=arange();
$from=$start->format('Y-m-d 00:00:00');$until=$end->modify('+1 day')->format('Y-m-d 00:00:00');
$dates=[$from,$until];
$page_title='ภาพรวมเว็บไซต์';$page_intro='ติดตามการเติบโต เรื่องราวการเดินทาง และรายการที่ต้องดูแล';
$ready=(int)av("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('analytics_events','analytics_visits','reports','admin_settings')")===4;
if(!$ready){$message='ยังไม่ได้ติดตั้งตารางใหม่ กรุณานำเข้า database/admin_upgrade.sql ในฐานข้อมูลเดิมก่อน';require 'header.php';echo '<section class="panel"><p>ไฟล์อัปเกรดเพิ่มเฉพาะตารางใหม่ ไม่ลบสมาชิกหรือทริปเดิม</p></section>';require 'footer.php';exit;}
$stats=aq('SELECT COUNT(DISTINCT visitor_hash) visitors, COUNT(DISTINCT visit_id) visits, COUNT(*) views, COUNT(DISTINCT user_id) active_members FROM analytics_events WHERE created_at>=? AND created_at<?','ss',$dates)[0];
$totalMembers=av("SELECT COUNT(*) FROM users WHERE role='user'");
$newMembers=av("SELECT COUNT(*) FROM users WHERE role='user' AND created_at>=? AND created_at<?",'ss',$dates);
$posts=av('SELECT COUNT(*) FROM trips WHERE created_at>=? AND created_at<?','ss',$dates);
$publicWhere="t.visibility='public' AND t.moderation_status='visible'";
$publicPosts=(int)av("SELECT COUNT(*) FROM trips t WHERE $publicWhere AND t.created_at>=? AND t.created_at<?",'ss',$dates);
$started=av("SELECT created_at FROM admin_settings WHERE setting_key='analytics_started'");
$monthly=$start->diff($end)->days>93;$format=$monthly?'%Y-%m':'%Y-%m-%d';
$visits=[];$cursor=$monthly?$start->modify('first day of this month'):$start;
while($cursor<=$end){$visits[$cursor->format($monthly?'Y-m':'Y-m-d')]=0;$cursor=$cursor->modify($monthly?'+1 month':'+1 day');}
foreach(aq("SELECT DATE_FORMAT(created_at,'$format') bucket,COUNT(DISTINCT visitor_hash) n FROM analytics_events WHERE created_at>=? AND created_at<? GROUP BY bucket ORDER BY bucket",'ss',$dates) as $r) $visits[$r['bucket']]=(int)$r['n'];
$monthlyPosts=[];$cursor=$start->modify('first day of this month');while($cursor<=$end){$monthlyPosts[$cursor->format('Y-m')]=0;$cursor=$cursor->modify('+1 month');}
foreach(aq("SELECT DATE_FORMAT(created_at,'%Y-%m') bucket,COUNT(*) n FROM trips WHERE created_at>=? AND created_at<? GROUP BY bucket ORDER BY bucket",'ss',$dates) as $r) $monthlyPosts[$r['bucket']]=(int)$r['n'];
$countries=aq("SELECT UPPER(TRIM(p.country_code)) label,COUNT(DISTINCT t.trip_id) n FROM trips t JOIN trip_places p ON p.trip_id=t.trip_id WHERE $publicWhere AND t.created_at>=? AND t.created_at<? AND COALESCE(TRIM(p.country_code),'')<>'' GROUP BY label ORDER BY n DESC,label LIMIT 10",'ss',$dates);
$provinces=aq("SELECT TRIM(p.province) label,COALESCE(p.country_code,'') country_code,COUNT(DISTINCT t.trip_id) n FROM trips t JOIN trip_places p ON p.trip_id=t.trip_id WHERE $publicWhere AND t.created_at>=? AND t.created_at<? AND TRIM(p.province) NOT IN ('','-','ไม่ระบุ') GROUP BY TRIM(p.province),COALESCE(p.country_code,'') ORDER BY n DESC,label LIMIT 10",'ss',$dates);
$countryNames=['TH'=>'ไทย','JP'=>'ญี่ปุ่น','KR'=>'เกาหลีใต้','CN'=>'จีน','SG'=>'สิงคโปร์','MY'=>'มาเลเซีย','VN'=>'เวียดนาม','LA'=>'ลาว','ID'=>'อินโดนีเซีย','FR'=>'ฝรั่งเศส','GB'=>'สหราชอาณาจักร','US'=>'สหรัฐอเมริกา'];
$unknownCountry=av("SELECT COUNT(*) FROM trips t WHERE $publicWhere AND t.created_at>=? AND t.created_at<? AND NOT EXISTS(SELECT 1 FROM trip_places p WHERE p.trip_id=t.trip_id AND COALESCE(TRIM(p.country_code),'')<>'')",'ss',$dates);
$popularRead=aq("SELECT t.trip_id,t.title,COUNT(*) n FROM analytics_events e JOIN trips t ON t.trip_id=e.trip_id WHERE $publicWhere AND e.created_at>=? AND e.created_at<? GROUP BY t.trip_id,t.title ORDER BY n DESC,t.trip_id DESC LIMIT 5",'ss',$dates);
$popularSave=aq("SELECT t.trip_id,t.title,COUNT(*) n FROM bookmarks b JOIN trips t ON t.trip_id=b.trip_id WHERE $publicWhere AND b.created_at>=? AND b.created_at<? GROUP BY t.trip_id,t.title ORDER BY n DESC,t.trip_id DESC LIMIT 5",'ss',$dates);
$newUsers=aq("SELECT user_id,fullname,username,created_at FROM users WHERE role='user' AND created_at>=? AND created_at<? ORDER BY created_at DESC,user_id DESC LIMIT 5",'ss',$dates);
// Dashboard and moderation UI never reveal another member's private trip content.
$latest=aq("SELECT t.trip_id,t.title,t.created_at,t.moderation_status,u.fullname FROM trips t JOIN users u ON u.user_id=t.user_id WHERE t.visibility='public' AND t.created_at>=? AND t.created_at<? ORDER BY t.created_at DESC,t.trip_id DESC LIMIT 6",'ss',$dates);
$pending=av("SELECT COUNT(*) FROM reports WHERE status='pending'");
$reportStats=aq('SELECT status,COUNT(*) n FROM reports WHERE created_at>=? AND created_at<? GROUP BY status','ss',$dates);
$reportNames=['pending'=>'รอตรวจสอบ','resolved'=>'ดำเนินการแล้ว','dismissed'=>'ยุติรายงาน'];
$photoFiles=aq("SELECT filename FROM (SELECT filename FROM place_photos UNION SELECT cover AS filename FROM trips UNION SELECT avatar AS filename FROM users) image_refs WHERE filename IS NOT NULL AND filename<>''");
$found=0;$missing=0;$linkedBytes=0;$diskBytes=0;$diskFiles=0;$storageReadable=is_dir(UPLOAD_DIR)&&is_readable(UPLOAD_DIR);
foreach($photoFiles as $r){$f=$r['filename'];if(!preg_match('/\A[a-f0-9]{48}\.(jpg|png|webp)\z/',$f)){ $missing++;continue; }$path=UPLOAD_DIR.'/'.$f;if(is_file($path)&&!is_link($path)&&is_readable($path)){$size=filesize($path);if($size!==false){$found++;$linkedBytes+=$size;}else $missing++;}else $missing++;}
if($storageReadable){try{foreach(new DirectoryIterator(UPLOAD_DIR) as $file){if($file->isFile()&&!$file->isLink()){$diskBytes+=$file->getSize();$diskFiles++;}}}catch(Throwable $e){$storageReadable=false;error_log($e->getMessage());}}
require 'header.php';
?>
<section class="panel"><form class="filters" method="get"><label>ช่วงเวลา<select name="period"><?php foreach(['today'=>'วันนี้','week'=>'7 วันรวมวันนี้','month'=>'เดือนนี้','year'=>'ปีนี้','custom'=>'กำหนดวันที่เอง'] as $key=>$label): ?><option value="<?= h($key) ?>" <?= $period===$key?'selected':'' ?>><?= h($label) ?></option><?php endforeach; ?></select></label><label>ตั้งแต่<input type="date" name="from" value="<?= $start->format('Y-m-d') ?>" max="<?= date('Y-m-d') ?>"></label><label>ถึง<input type="date" name="to" value="<?= $end->format('Y-m-d') ?>" max="<?= date('Y-m-d') ?>"></label><button class="btn">แสดงข้อมูล</button></form><p class="muted">ช่วงที่แสดง <?= $start->format('d/m/Y') ?> – <?= $end->format('d/m/Y') ?> · ช่องวันที่ใช้เมื่อเลือก “กำหนดวันที่เอง”</p></section>
<div class="cards">
<?php foreach([
['ผู้เข้าชมไม่ซ้ำ',$stats['visitors'],'ตามรหัสเบราว์เซอร์ในช่วงที่เลือก'],['สมาชิกทั้งหมด',$totalMembers,'ยอดปัจจุบัน ไม่รวมบัญชีแอดมิน'],['สมาชิกใหม่',$newMembers,'สมัครในช่วงที่เลือก'],['โพสต์ทริปใหม่',$posts,'รวมสาธารณะ ส่วนตัว และถูกซ่อน'],['รอบเข้าชม',$stats['visits'],'รอบที่มีกิจกรรมในช่วงที่เลือก'],['หน้าที่เปิดดู',$stats['views'],'รวมการเปิดซ้ำ'],['สมาชิกที่ใช้งาน',$stats['active_members'],'บัญชีที่เปิดหน้าในช่วงที่เลือก'],['รอตรวจสอบ',$pending,'รายงานค้างทั้งหมด ไม่จำกัดช่วงเวลา']
] as $i=>$card): ?><article class="stat <?= $i===0?'primary':'' ?>"><span><?= h($card[0]) ?></span><strong><?= afmt($card[1]) ?></strong><p class="muted"><?= h($card[2]) ?></p></article><?php endforeach; ?>
</div>
<p class="muted">เริ่มเก็บสถิติ <?= h($started) ?> · ไม่นับบัญชีแอดมินและบอตที่ตรวจพบ · เบราว์เซอร์/อุปกรณ์ต่างกันอาจนับเป็นคนละผู้เข้าชม · วันที่ก่อนเริ่มเก็บยังไม่มีข้อมูล ไม่ใช่ยอดผู้เข้าชมเป็นศูนย์จริง</p>
<div class="grid-two"><section class="panel"><h2>แนวโน้มผู้เข้าชม</h2><p class="muted">ผู้เข้าชมไม่ซ้ำต่อ<?= $monthly?'เดือน':'วัน' ?> — ผลรวมแต่ละจุดอาจมากกว่ายอดไม่ซ้ำทั้งช่วง</p><?php achart($visits,'line','กราฟผู้เข้าชมไม่ซ้ำ'); ?></section><section class="panel"><h2>การโพสต์ทริปรายเดือน</h2><p class="muted">นับวันที่สร้างโพสต์ เฉพาะวันที่อยู่ในช่วงที่เลือก</p><?php achart($monthlyPosts,'bar','จำนวนโพสต์ใหม่รายเดือน'); ?></section></div>
<div class="grid-two"><?php foreach(['ประเทศยอดนิยม'=>$countries,'จังหวัด / เมืองยอดนิยม'=>$provinces] as $heading=>$rows): ?><section class="panel"><h2><?= h($heading) ?></h2><p class="muted">จาก <?= afmt($publicPosts) ?> โพสต์สาธารณะที่ไม่ถูกซ่อน สร้างในช่วงที่เลือก</p><?php if(!$rows): ?><p class="empty">ยังไม่มีข้อมูลพื้นที่</p><?php endif; ?><?php foreach($rows as $i=>$r): $percent=$publicPosts ? $r['n']/$publicPosts*100:0;$label=isset($r['country_code'])?$r['label'].' · '.($countryNames[$r['country_code']]??$r['country_code']):($countryNames[$r['label']]??$r['label']); ?><div class="rank"><span class="number"><?= $i+1 ?></span><div><strong><?= h($label) ?></strong><svg viewBox="0 0 100 5" preserveAspectRatio="none" aria-hidden="true"><rect width="<?= round($percent,2) ?>" height="5" rx="2"/></svg></div><span><?= afmt($r['n']) ?> ทริป<small><?= number_format($percent,1) ?>%</small></span></div><?php endforeach; ?><p class="muted">หนึ่งทริปอาจมีหลายพื้นที่ เปอร์เซ็นต์รวมจึงอาจเกิน 100% นับทริปเดิมในพื้นที่เดียวเพียงครั้งเดียว</p></section><?php endforeach; ?></div>
<p class="muted">โพสต์ไม่ระบุประเทศ <?= afmt($unknownCountry) ?> ทริป · จังหวัดที่ว่างหรือ “-” ไม่นำมาจัดอันดับ</p>
<div class="grid-two"><?php foreach(['ทริปที่เปิดอ่านมากที่สุด'=>$popularRead,'ทริปที่บันทึกไว้มากที่สุด'=>$popularSave] as $heading=>$rows): ?><section class="panel"><h2><?= h($heading) ?></h2><p class="muted"><?= $heading==='ทริปที่เปิดอ่านมากที่สุด'?'ยอดเปิดหน้ารายละเอียดในช่วงที่เลือก รวมเปิดซ้ำ':'รายการบันทึกที่สร้างในช่วงที่เลือกและยังไม่ยกเลิก' ?></p><?php if(!$rows): ?><p class="empty">ยังไม่มีข้อมูลในช่วงนี้</p><?php endif; ?><?php foreach($rows as $i=>$r): ?><div class="rank"><span><?= $i+1 ?></span><a href="../trip_detail.php?id=<?= (int)$r['trip_id'] ?>"><?= h($r['title']) ?></a><strong><?= afmt($r['n']) ?></strong></div><?php endforeach; ?></section><?php endforeach; ?></div>
<div class="grid-two"><section class="panel"><div class="section-top"><h2>สมาชิกใหม่ล่าสุด</h2><a href="members.php">จัดการสมาชิก →</a></div><div class="table-wrap"><table><thead><tr><th>สมาชิก</th><th>วันที่สมัคร</th><th></th></tr></thead><tbody><?php foreach($newUsers as $r): ?><tr><td><?= h($r['fullname']) ?><p class="muted">@<?= h($r['username']) ?></p></td><td><?= h($r['created_at']) ?></td><td><a href="members.php?q=<?= h(rawurlencode($r['username'])) ?>">จัดการ</a></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$newUsers): ?><p class="empty">ไม่มีสมาชิกใหม่ในช่วงนี้</p><?php endif; ?></section>
<section class="panel"><div class="section-top"><h2>โพสต์สาธารณะล่าสุด</h2><a href="trips.php">จัดการโพสต์ →</a></div><div class="table-wrap"><table><thead><tr><th>ทริป / ผู้โพสต์</th><th>วันที่โพสต์</th><th>จัดการ</th></tr></thead><tbody><?php foreach($latest as $r): ?><tr><td><a href="../trip_detail.php?id=<?= (int)$r['trip_id'] ?>"><?= h($r['title']) ?></a><p class="muted"><?= h($r['fullname']) ?></p><span class="badge"><?= $r['moderation_status']==='hidden'?'ถูกซ่อน':'เผยแพร่' ?></span></td><td><?= h($r['created_at']) ?></td><td><a href="trips.php?id=<?= (int)$r['trip_id'] ?>"><?= $r['moderation_status']==='hidden'?'คืนสถานะ':'ซ่อนพร้อมเหตุผล' ?></a></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$latest): ?><p class="empty">ไม่มีโพสต์สาธารณะในช่วงนี้</p><?php endif; ?></section></div>
<div class="grid-two"><section class="panel"><div class="section-top"><h2>รายงานปัญหา</h2><a href="reports.php">ตรวจสอบรายงาน →</a></div><p>รอตรวจสอบทั้งหมด <strong><?= afmt($pending) ?></strong> เรื่อง</p><?php foreach($reportStats as $r): ?><div class="rank"><span>•</span><span><?= h($reportNames[$r['status']]) ?> (รายงานที่ส่งในช่วงนี้)</span><strong><?= afmt($r['n']) ?></strong></div><?php endforeach; ?><?php if(!$reportStats): ?><p class="empty">ไม่มีรายงานใหม่ในช่วงนี้</p><?php endif; ?></section>
<section class="panel"><h2>พื้นที่รูปภาพปัจจุบัน</h2><?php if(!$storageReadable): ?><p class="error">อ่านโฟลเดอร์อัปโหลดไม่ได้ กรุณาตรวจสิทธิ์โฟลเดอร์</p><?php else: ?><p class="storage-number"><?= abytes($diskBytes) ?></p><p>ไฟล์ทั้งหมดในโฟลเดอร์อัปโหลด <?= afmt($diskFiles) ?> ไฟล์</p><p class="muted">รูปที่ฐานข้อมูลอ้างถึงและพบไฟล์ <?= afmt($found) ?> รูป (<?= abytes($linkedBytes) ?>) รวมปกทริป รูปสถานที่ และรูปโปรไฟล์</p><p class="muted">อ้างอิงรูปที่หาไฟล์ไม่พบ/อ่านไม่ได้ <?= afmt($missing) ?> รายการ · ยอดปัจจุบัน ไม่ใช่ยอดตามตัวกรองวันที่</p><?php endif; ?></section></div>
<?php require 'footer.php'; ?>
